// After fetching initial Rayvn log entries, set the starting timestamps
// so that polling only picks up NEW entries from this point forward
const connection = msg.connection;

if (!connection) {
    node.warn("No connection on msg for initial timestamp");
    return msg;
}

const data = global.get("parat_bridge");
const conn = data.connections.find(c => c.id === connection.id);

if (conn) {
    const lastEntry = Array.isArray(msg.payload) && msg.payload.at(-1);
    conn.timestamps.last_rayvn = lastEntry?.timeCreated || Date.now();
    conn.timestamps.last_wasos = Date.now();
    global.set("parat_bridge", data);
}

return msg;

// Base URLs for all API calls — single source of truth
const BASE_URLS = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};

// Preserve existing data across restarts
let data = global.get("parat_bridge") || null;

if (!data) {
    // Fresh install — create empty structure
    data = {
        base_urls: BASE_URLS,
        connections: []
    };
} else {
    // Existing install — update base URLs, keep connections intact
    data.base_urls = BASE_URLS;

    // --- MIGRATION: Move global queue to per-connection queues ---
    // TODO: Remove this block after all connections have been recreated (added 2026-02-24)
    if (data.queue && data.queue.length > 0) {
        data.queue.forEach(entry => {
            const connection = data.connections.find(c => c.id === entry.connection_id);
            if (connection) {
                if (!connection.queue) connection.queue = [];
                connection.queue.push(entry);
            }
        });
        delete data.queue;
    }

    // --- MIGRATION: Move global master_log to per-connection master_logs ---
    // TODO: Remove this block after all connections have been recreated (added 2026-02-24)
    if (data.master_log && data.master_log.length > 0) {
        data.master_log.forEach(entry => {
            const connection = data.connections.find(c => c.id === entry.connection_id);
            if (connection) {
                if (!connection.master_log) connection.master_log = [];
                connection.master_log.push(entry);
            }
        });
        delete data.master_log;
    }

    // Ensure every connection has queue and master_log arrays
    data.connections.forEach(connection => {
        if (!connection.queue) connection.queue = [];
        if (!connection.master_log) connection.master_log = [];
    });
}

global.set("parat_bridge", data);

// Clean up the old pb helper object from previous version
global.set("pb", undefined);

node.log("Parat-Bridge initialized: " + data.connections.length + " connection(s)");
msg.payload = data;
return msg;

const data = global.get("parat_bridge");

const rayvnConfig = msg.payload.rayvn_configured;
const wasosConfig = msg.payload.wasos_configured;

if (!rayvnConfig || !wasosConfig) {
    node.error("Missing configuration — join node did not deliver both systems");
    return null;
}

// Check if this exact pairing already exists
const existingConnection = data.connections.find(c =>
    c.rayvn.log_id === rayvnConfig.log_id &&
    c.wasos.chatroom_name === wasosConfig.chatroom_name
);

let connection;

if (existingConnection) {
    // Update credentials for existing connection (e.g. after token refresh)
    existingConnection.rayvn = {
        api_key: rayvnConfig.api_key,
        log_name: rayvnConfig.log_name,
        log_id: rayvnConfig.log_id
    };
    existingConnection.wasos = {
        username: wasosConfig.username,
        chatroom_name: wasosConfig.chatroom_name,
        user_id: wasosConfig.user_id || null,
        group: wasosConfig.group || null,
        api: {
            key: wasosConfig.api_key || (wasosConfig.api && wasosConfig.api.key),
            expires: wasosConfig.expires || (wasosConfig.api && wasosConfig.api.expires)
        }
    };
    existingConnection.active = true;
    connection = existingConnection;
    node.log("Updated existing connection: " + connection.label);
} else {
    // Create new connection with unique ID
    const connectionId = "conn_" + (data.connections.length + 1) + "_" + Date.now().toString(36);

    connection = {
        id: connectionId,
        label: (rayvnConfig.log_name || "Rayvn") + " ↔ " + (wasosConfig.chatroom_name || "WaSOS"),
        rayvn: {
            api_key: rayvnConfig.api_key,
            log_name: rayvnConfig.log_name,
            log_id: rayvnConfig.log_id
        },
        wasos: {
            username: wasosConfig.username,
            chatroom_name: wasosConfig.chatroom_name,
            user_id: wasosConfig.user_id || null,
            group: wasosConfig.group || null,
            api: {
                key: wasosConfig.api_key || (wasosConfig.api && wasosConfig.api.key),
                expires: wasosConfig.expires || (wasosConfig.api && wasosConfig.api.expires)
            }
        },
        timestamps: { last_rayvn: 0, last_wasos: 0 },
        active: true,
        queue: [],
        master_log: []
    };

    data.connections.push(connection);
    node.log("Created new connection: " + connection.label);
}

global.set("parat_bridge", data);

msg.connection = connection;
msg.payload = connection;
return msg;

const pb = global.get("pb");
const conns = pb.getConnections();

msg.payload = conns.map(c => ({
    "Navn": c.label,
    "Status": c.active ? "✅ Aktiv" : "⏸️ Inaktiv",
    "ID": c.id
}));

return msg;
